    { id: 2, user: 'Sarah Smith', action: 'Virtual Try-On Completed', time: '5 mins ago' },
    { id: 3, user: 'Mike Johnson', action: 'Account Created', time: '10 mins ago' },
    { id: 4, user: 'Emma Wilson', action: 'Product Review Added', time: '15 mins ago' }
  ];

  if (!adminUser) {
    return <div className="loading">Loading...</div>;
  }

  return (
    <div className="admin-dashboard">
      {/* Header */}
      <header className="admin-header">
        <div className="admin-header-left">
          <h1>SmartStyle Admin Dashboard</h1>
          <p>Welcome back, {adminUser.name}</p>
        </div>
        <div className="admin-header-right">
          <span className="admin-role">Administrator</span>
          <button onClick={handleLogout} className="logout-btn">
            Logout
          </button>
        </div>
      </header>

      <div className="admin-container">
        {/* Sidebar */}
        <nav className="admin-sidebar">
          <div className="sidebar-menu">
            <button className={`menu-item ${activeTab === 'overview' ? 'active' : ''}`} onClick={() => setActiveTab('overview')}>
              <span>📊</span> Store Overview
            </button>
            <button className={`menu-item ${activeTab === 'orders' ? 'active' : ''}`} onClick={() => setActiveTab('orders')}>
              <span>📦</span> Orders
            </button>
            <button className={`menu-item ${activeTab === 'products' ? 'active' : ''}`} onClick={() => setActiveTab('products')}>
              <span>👕</span> Inventory
            </button>
            <button className={`menu-item ${activeTab === 'customers' ? 'active' : ''}`} onClick={() => setActiveTab('customers')}>
              <span>👥</span> Customers
            </button>
            <button className={`menu-item ${activeTab === 'settings' ? 'active' : ''}`} onClick={() => setActiveTab('settings')}>
              <span>⚙️</span> Store Settings
            </button>
            <button className={`menu-item ${activeTab === 'promotions' ? 'active' : ''}`} onClick={() => setActiveTab('promotions')}>
              <span>📢</span> Promotions
            </button>
            <button className={`menu-item ${activeTab === 'reviews' ? 'active' : ''}`} onClick={() => setActiveTab('reviews')}>
              <span>⭐</span> Review Management
            </button>
          </div>
        </nav>

        {/* Main Content */}
        <main className="admin-main">
          {activeTab === 'overview' && (
            <div className="overview-tab">
              <h2>Dashboard Overview</h2>

              {/* Stats Grid */}
              <div className="stats-grid">
                <div className="stat-card">
                  <div className="stat-icon">👥</div>
                  <div className="stat-info">
                    <h3>{dashboardStats.totalUsers}</h3>
                    <p>Total Users</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">👕</div>
                  <div className="stat-info">
                    <h3>{dashboardStats.totalProducts}</h3>
                    <p>Products</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">📦</div>
                  <div className="stat-info">
                    <h3>{dashboardStats.totalOrders}</h3>
                    <p>Total Orders</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">💰</div>
                  <div className="stat-info">
                    <h3>{dashboardStats.revenue}</h3>
                    <p>Revenue</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">🎯</div>
                  <div className="stat-info">
                    <h3>{dashboardStats.activeTryOns}</h3>
                    <p>Active Try-Ons</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">📊</div>
                  <div className="stat-info">
                    <h3>{dashboardStats.conversionRate}</h3>
                    <p>Conversion Rate</p>
                  </div>
                </div>
              </div>

              {/* Recent Activity */}
              <div className="recent-activity">
                <h3>Recent Activity</h3>
                <div className="activity-list">
                  {recentActivities.map(activity => (
                    <div key={activity.id} className="activity-item">
                      <div className="activity-content">
                        <strong>{activity.user}</strong> {activity.action}
                      </div>
                      <span className="activity-time">{activity.time}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'orders' && (
            <div className="orders-tab">
              <div className="card-header">
                <h2>Manage Orders</h2>
                <div className="orders-header-actions">
                  <input
                    type="text"
                    placeholder="Search by Order ID or Email..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="admin-search-input"
                  />
                  <button className="primary-btn" onClick={() => setActiveTab('overview')}>← Overview</button>
                </div>
              </div>

              <div className="content-card">
                {ordersLoading ? (
                  <p>Loading orders...</p>
                ) : (
                  <table className="admin-table">
                    <thead>
                      <tr>
                        <th>Order ID</th>
                        <th>Customer</th>
                        <th>Status</th>
                        <th>Amount</th>
                        <th>Actions</th>
                        <th>Details</th>
                      </tr>
                    </thead>
                    <tbody>
                      {Array.isArray(allOrders) && allOrders
                        .filter(order =>
                          order._id.toString().includes(searchTerm) ||
                          order.customerId.toLowerCase().includes(searchTerm.toLowerCase())
                        )
                        .length > 0 ? (
                        allOrders
                          .filter(order =>
                            order._id.toString().includes(searchTerm) ||
                            order.customerId.toLowerCase().includes(searchTerm.toLowerCase())
                          )
                          .map((order) => (
                            <tr key={order._id}>
                              <td><strong>#RD-{order._id.toString().slice(-6).toUpperCase()}</strong></td>
                              <td>{order.customerId}</td>
                              <td>
                                <span className={`status-pill ${order.status?.toLowerCase() || 'pending'}`}>
                                  {order.status || 'Pending'}
                                </span>
                              </td>
                              <td>₹{order.totalAmount?.toLocaleString()}</td>
                              <td>
                                <select
                                  value={order.status || 'Pending'}
                                  onChange={(e) => updateOrderStatus(order._id, e.target.value)}
                                  className="status-select"
                                >
                                  <option value="Pending">Pending</option>
                                  <option value="Processing">Processing</option>
                                  <option value="Shipped">Shipped</option>
                                  <option value="Delivered">Delivered</option>
                                  <option value="Cancelled">Cancelled</option>
                                </select>
                              </td>
                              <td>
                                <button className="modal-trigger-btn" onClick={() => setSelectedOrder(order)}>
                                  View Details
                                </button>
                              </td>
                            </tr>
                          ))
                      ) : (
                        <tr><td colSpan="5" style={{ textAlign: 'center', padding: '20px' }}>No matching orders found.</td></tr>
                      )}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          )}

          {activeTab === 'products' && (
            <div className="products-tab">
              <h2>Product Catalog</h2>
              <p>Product management interface coming soon...</p>
            </div>
          )}

          {activeTab === 'orders' && (
            <div className="orders-tab">
              <h2>Order Management</h2>
              <p>Order management interface coming soon...</p>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="settings-tab">
              <div className="card-header">
                <h2>Global Store Settings</h2>
                <button className="primary-btn" onClick={saveSettings}>Save Configurations</button>
              </div>

              <div className="settings-grid">
                {/* System Toggles */}
                <div className="content-card settings-card" style={{ maxWidth: '400px', margin: '0 auto' }}>
                  <h3>Platform Configuration</h3>
                  <div className="settings-form">
                    <div className="toggle-group">
                      <div className="toggle-info">
                        <strong>Maintenance Mode</strong>
                        <span>Temporarily disable the storefront for users</span>
                      </div>
                      <label className="switch">
                        <input
                          type="checkbox"
                          name="maintenanceMode"
                          checked={storeSettings.maintenanceMode}
                          onChange={handleSettingChange}
                        />
                        <span className="slider round"></span>
                      </label>
                    </div>

                    <div className="form-group">
                      <label>Official Helpline Number</label>
                      <input
                        type="text"
                        name="helpline"
                        placeholder="+91 1800-123-4567"
                        value={storeSettings.helpline || ''}
                        onChange={handleSettingChange}
                      />
                    </div>

                    <div className="form-group">
                      <label>Official Support Email</label>
                      <input
                        type="email"
                        name="officialEmail"
                        placeholder="support@smartstyle.com"
                        value={storeSettings.officialEmail || ''}
                        onChange={handleSettingChange}
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'promotions' && (
            <div className="promotions-tab">
              <div className="card-header">
                <h2>📢 Banner Management</h2>
              </div>

              <div className="content-card">
                <div className="form-group">
                  <label>Banner Title</label>
                  <input id="bannerTitle" type="text" placeholder="e.g. Summer Sale" className="admin-search-input" style={{ width: '100%', marginBottom: '10px' }} />
                </div>
                <div className="form-group">
                  <label>Target Link (Optional)</label>
                  <input id="bannerLink" type="text" placeholder="e.g. category=Summer" className="admin-search-input" style={{ width: '100%', marginBottom: '10px' }} />
                </div>
                <div className="form-group">
                  <label>Banner Image</label>
                  <input id="bannerImage" type="file" accept="image/*" className="admin-search-input" style={{ width: '100%', marginBottom: '10px' }} />
                </div>
                <button className="primary-btn" onClick={async () => {
                  const title = document.getElementById('bannerTitle').value;
                  const link = document.getElementById('bannerLink').value;
                  const file = document.getElementById('bannerImage').files[0];

                  if (!title || !file) return alert("Title and Image required");

                  const formData = new FormData();
                  formData.append('title', title);
                  formData.append('link', link);
                  formData.append('image', file);

                  try {
                    await fetch('http://localhost:5000/api/banners', { method: 'POST', body: formData });
                    alert("✅ Banner Uploaded");
                    // Trigger refresh
                    setActiveTab('overview');
                    setTimeout(() => setActiveTab('promotions'), 100);
                  } catch (e) { console.error(e); alert("Failed"); }
                }}>Upload Banner</button>
              </div>

              <div className="content-card" style={{ marginTop: '20px' }}>
                <h3>Active Banners</h3>
                <div className="banner-list" style={{ display: 'grid', gap: '10px' }}>
                  {banners.map(b => (
                    <div key={b._id} style={{ border: '1px solid #eee', padding: '10px', display: 'flex', alignItems: 'center', gap: '10px' }}>
                      <img src={`http://localhost:5000${b.image}`} style={{ width: '100px', height: '50px', objectFit: 'cover' }} alt="" />
                      <div style={{ flex: 1 }}>
                        <strong>{b.title}</strong>
                        <p style={{ fontSize: '0.8rem', color: '#666' }}>{b.link}</p>
                      </div>
                      <button className="delete-icon-btn" onClick={async () => {
                        if (!window.confirm("Delete?")) return;
                        await fetch(`http://localhost:5000/api/banners/${b._id}`, { method: 'DELETE' });
                        setBanners(prev => prev.filter(x => x._id !== b._id));
                      }}>🗑️</button>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'reviews' && (
            <div className="reviews-tab">
              <div className="card-header">
                <h2>⭐ Review Moderation</h2>
                <p>Monitor and delete inappropriate reviews.</p>
              </div>

              <div className="content-card" style={{ marginTop: '20px' }}>
                {reviews.length === 0 ? <p>No reviews found.</p> : (
                  <div className="reviews-list" style={{ display: 'grid', gap: '15px' }}>
                    {reviews.map(r => (
                      <div key={r.reviewId} style={{ border: '1px solid #eee', padding: '15px', borderRadius: '8px', background: 'white' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                          <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                            <img src={`http://localhost:5000${r.productImage}`} style={{ width: '40px', height: '40px', objectFit: 'cover', borderRadius: '4px' }} alt="" />
                            <div>
                              <strong>{r.productName}</strong>
                              <div style={{ fontSize: '0.85rem', color: '#666' }}>By: {r.user} | {new Date(r.date).toLocaleDateString()}</div>
                            </div>
                          </div>
                          <div style={{ fontWeight: 'bold', color: '#e91e63' }}>{r.rating} ★</div>
                        </div>
                        <p style={{ background: '#f9f9f9', padding: '10px', borderRadius: '4px', fontStyle: 'italic' }}>"{r.comment}"</p>
                        <div style={{ textAlign: 'right', marginTop: '10px' }}>
                          <button
                            style={{ background: '#ff4d4d', color: 'white', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }}
                            onClick={async () => {
                              if (!window.confirm("Delete this review?")) return;
                              try {
                                await fetch(`http://localhost:5000/api/reviews/${r.productId}/${r.reviewId}`, { method: 'DELETE' });
                                setReviews(prev => prev.filter(x => x.reviewId !== r.reviewId));
                              } catch (e) { alert("Failed to delete"); }
                            }}
                          >
                            Delete Review
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab !== 'overview' && activeTab !== 'orders' && activeTab !== 'products' && activeTab !== 'customers' && activeTab !== 'settings' && activeTab !== 'promotions' && activeTab !== 'reviews' && (
            <div className="placeholder-tab">
              <h2>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)} Module</h2>
              <p>Advanced e-commerce controls for {activeTab} coming soon.</p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default AdminDashboard;

// src/pages/CustomerDashboard.js
import axios from "axios";
import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import "./CustomerDashboard.css";
import { useCart } from "../context/CartContext";
import { useWishlist } from "../context/WishlistContext";
import { toast } from "react-toastify";
import AvatarViewer from "../components/AvatarViewer";

const CustomerDashboard = ({ user, onLogout }) => {
  const navigate = useNavigate();
  const location = useLocation();

  // SAFE default customer object so it's never null
  const [customer, setCustomer] = useState(
    user || {
      name: "",
      email: "",
      phone: "",
      gender: "",
      addressLine1: "",
      addressLine2: "",
      city: "",
      pincode: ""
    }
  );
  const [measurements, setMeasurements] = useState(() => {
    const saved = localStorage.getItem("userMeasurements");
    // Ensure all fields exist
    const parsed = saved ? JSON.parse(saved) : {};
    return {
      height: parsed.height || "",
      weight: parsed.weight || "",
      chest: parsed.chest || "",
      waist: parsed.waist || "",
      hips: parsed.hips || "",
      thigh: parsed.thigh || "",
      shoulders: parsed.shoulders || "",
      gender: parsed.gender || "", // Added Gender
    };
  });

  const [generatedMeasurements, setGeneratedMeasurements] = useState({ ...measurements });

  // If we have saved data, start in view-only mode
  const [isMeasurementEditable, setIsMeasurementEditable] = useState(() => {
    return !localStorage.getItem("userMeasurements");
  });

  const handleGenerateAvatar = () => {
    setGeneratedMeasurements({ ...measurements });
    localStorage.setItem("userMeasurements", JSON.stringify(measurements));
    setIsMeasurementEditable(false);
    toast.success("Avatar generated & saved!");
  };

  const [activeTab, setActiveTab] = useState(location.state?.activeTab || "home");
  const [avatarPhoto, setAvatarPhoto] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [products, setProducts] = useState([]);
  const [orderHistory, setOrderHistory] = useState([]);

  const [selectedClothing, setSelectedClothing] = useState(null);
  const [recommendations, setRecommendations] = useState([]);
  const [showCategoryDropdown, setShowCategoryDropdown] = useState(false);
  const [showSortDropdown, setShowSortDropdown] = useState(false);
  const [sortBy, setSortBy] = useState("relevance"); // Default sort

  const dropdownRef = React.useRef(null);
  const sortDropdownRef = React.useRef(null);

  // Close dropdowns when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setShowCategoryDropdown(false);
      }
      if (sortDropdownRef.current && !sortDropdownRef.current.contains(event.target)) {
        setShowSortDropdown(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const SORT_OPTIONS = [
    { label: "Relevance", value: "relevance" },
    { label: "Newest First", value: "newest" },
    { label: "Price: Low to High", value: "price_asc" },
    { label: "Price: High to Low", value: "price_desc" },
    { label: "Top Rated", value: "rating" },
  ];

  const CATEGORY_OPTIONS = {
    "Men": { icon: "👨", items: ["Shirts", "T-Shirts", "Jeans", "Trousers", "Jackets", "Suits", "Kurtas"] },
    "Women": { icon: "👩", items: ["Dresses", "Tops", "Jeans", "Skirts", "Sarees", "Lehengas", "Kurtas"] },
    "Kids": { icon: "🧸", items: ["T-Shirts", "Shorts", "Dresses", "Sets", "Bodysuits"] },
    "Accessories": { icon: "👜", items: ["Watches", "Bags", "Shoes", "Jewelry", "Belts", "Sunglasses"] }
  };

  // Filter State
  const [filters, setFilters] = useState({
    category: "",
    minPrice: "",
    maxPrice: "",
    gender: "",
    brand: "",
    minRating: ""
  });
  const [showFilterDrawer, setShowFilterDrawer] = useState(false);
  const [brands, setBrands] = useState([]); // Dynamic brands

  // Cart & wishlist contexts
  const { addToCart, cart, updateQuantity, removeFromCart, clearCart, getCartTotal } = useCart();
  const { wishlist, addToWishlist, removeFromWishlist, isWishlisted } = useWishlist();

  // --- Fetch profile (if email exists) safely ---
  useEffect(() => {
    if (!customer?.email) return;

    axios
      .get(`http://localhost:5000/api/customer/${encodeURIComponent(customer.email)}`)
      .then((res) => {
        if (res.data) setCustomer(res.data);
      })
      .catch((err) => console.log("❌ Failed to load profile", err));
  }, [customer.email]);



  // --- Fetch Brands ---
  useEffect(() => {
    axios.get("http://localhost:5000/api/products/brands")
      .then(res => setBrands(res.data))
      .catch(err => console.error("Failed to fetch brands", err));
  }, []);

  // --- Fetch products with filters ---
  const fetchProducts = () => {
    // Construct query params
    const params = new URLSearchParams();
    if (searchTerm) params.append("search", searchTerm);
    if (filters.category) params.append("category", filters.category);
    if (filters.minPrice) params.append("minPrice", filters.minPrice);
    if (filters.maxPrice) params.append("maxPrice", filters.maxPrice);
    if (filters.gender) params.append("gender", filters.gender);
    if (filters.brand) params.append("brand", filters.brand);

    // Sort Param
    if (sortBy && sortBy !== "relevance") params.append("sort", sortBy);

    console.log("🔍 Fetching Products with Params:", params.toString()); // DEBUG LOG

    axios
      .get(`http://localhost:5000/api/products?${params.toString()}`)
      .then((res) => {
        console.log("📦 Products Received:", res.data.length); // DEBUG LOG
        if (res.data) setProducts(res.data);
      })
      .catch((err) => console.log("❌ Failed to load products", err));
  };

  // Re-fetch when filters, search, or sort change
  useEffect(() => {
    fetchProducts();
  }, [filters, searchTerm, sortBy]); // Auto-fetch on change

  // --- Fetch Orders ---
  useEffect(() => {
    if (activeTab === "orders" && customer?.email) {
      axios.get(`http://localhost:5000/api/orders/customer/${encodeURIComponent(customer.email)}`)
        .then(res => setOrderHistory(res.data))
        .catch(err => console.error("Failed to load orders", err));
    }
  }, [activeTab, customer]);

  // Optional debug
  const [banners, setBanners] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:5000/api/banners')
      .then(res => {
        if (Array.isArray(res.data)) setBanners(res.data);
        else setBanners([]);
      })
      .catch(err => console.log(err));

  }, []);

  // --- Fetch Recommendations ---
  useEffect(() => {
    const uid = customer?.userId || user?._id || user?.id;
    if (uid && activeTab === "home") {
      axios.get(`http://localhost:5000/api/products/recommendations?userId=${uid}`)
        .then(res => setRecommendations(res.data))
        .catch(err => console.error("Failed to fetch recommendations", err));
    }
  }, [customer, user, activeTab]);

  useEffect(() => {
    // uncomment while debugging
    // console.log("CUSTOMER STATE =>", customer);
  }, [customer]);

  const handleLogout = () => {
    onLogout();
    navigate("/");
  };

  const handlePhotoUpload = (e) => {
    const file = e.target.files[0];
    if (file) setAvatarPhoto(URL.createObjectURL(file));
  };
  const handleMeasurementChange = (e) => {
    setMeasurements({ ...measurements, [e.target.name]: e.target.value });
  };

  // Update profile on backend (PUT). Backend must return updated customer.
  const handleProfileUpdate = async () => {
    try {
      if (!customer?.email) {
        toast.error("No email present for this user.");
        return;
      }

      // Ensure userId is present (from user prop or existing customer state)
      const payload = {
        ...customer,
        userId: customer.userId || user.id || user._id,
      };

      const res = await axios.put(
        `http://localhost:5000/api/customer/${encodeURIComponent(customer.email)}`,
        payload
      );

      if (res.data) {
        setCustomer(res.data);
        localStorage.setItem("user", JSON.stringify(res.data));
        toast.success("✔ Profile updated successfully!");
      } else {
        toast.error("❌ Unexpected response from server.");
      }
    } catch (err) {
      console.error(err);
      const errorMsg = err.response?.data?.details || err.response?.data?.error || "Failed to save profile";
      toast.error(`❌ ${errorMsg}`);
    }
  };

  // Place order handler (redirects to payment)
  const handlePlaceOrder = () => {
    if (!cart.items.length) {
      toast.error("Cart is empty");
      return;
    }

    // Navigate to payment page with cart details
    navigate("/payment", {
      state: {
        items: cart.items,
        totalAmount: getCartTotal(),
        customer: customer
      }
    });
  };

  return (
    <div className="customer-dashboard">
      {/* HEADER */}
      <header className="dashboard-header">
        <div className="logo" onClick={() => setActiveTab("home")}>SmartStyle</div>

        <div className="search-container">
          <input
            type="text"
            placeholder="Search for products, brands and more"
            value={searchTerm}
            className="search-bar"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <span className="search-icon-inside">🔍</span>
        </div>

        <div className="header-icons">
          <div className={`cart-icon ${cart.items.length ? "bump" : ""}`} onClick={() => setActiveTab("cart")}>
            🛒 <span className="badge">{cart.items.length}</span>
          </div>
          <button className="logout-btn" onClick={handleLogout}>Logout</button>
        </div>
      </header>

      <div className="dashboard-body">
        <aside className="profile-sidebar">
          {["home", "wishlist", "cart", "orders", "profile", "avatar", "history"].map((tab) => (
            <div
              key={tab}
              className={`sidebar-tab ${activeTab === tab ? "active" : ""}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab.toUpperCase()}
            </div>
          ))}
        </aside>

        <main className="dashboard-main">
          {/* HOME */}
          {activeTab === "home" && (
            <div className="home-container">

              {/* 🆕 PROMOTIONAL BANNERS CAROUSEL */}
              {banners.length > 0 && (
                <div className="banner-carousel-container" style={{
                  width: '100%',
                  overflowX: 'auto',
                  whiteSpace: 'nowrap',
                  marginBottom: '20px',
                  borderRadius: '12px',
                  boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
                }}>
                  <div style={{ display: 'flex', gap: '10px' }}>
                    {banners.map(b => (
                      <div key={b._id} style={{ position: 'relative', minWidth: '100%', height: '300px', flexShrink: 0 }}>
                        <img
                          src={b.image.startsWith("http") ? b.image : `http://localhost:5000${b.image}`}
                          alt={b.title}
                          style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: '12px', cursor: 'pointer' }}
                          onClick={() => {
                            if (b.link) {
                              if (b.link.includes('category=')) {
                                const cat = b.link.split('=')[1];
                                setFilters({ ...filters, category: cat });
                                toast.info(`Filtering by ${cat}`);
                              }
                            }
                          }}
                        />
                      </div>
                    ))}
                  </div>
                </div>

              )}

              {/* ⭐ RECOMMENDATIONS SECTION ⭐ */}
              {recommendations.length > 0 && (
                <div className="recommendations-section" style={{ marginBottom: "30px", padding: "0 10px" }}>
                  <h3 style={{ color: "#333", fontSize: "1.2rem", marginBottom: "15px" }}>Recommended for You ✨</h3>
                  <div className="catalog-grid-smart">
                    {recommendations.map((product) => (
                      <div key={product._id} className="smart-product-card">
                        <div className="card-image-container" onClick={() => navigate(`/product/${product._id}`, { state: product })} style={{ cursor: "pointer" }}>
                          {/* Label for Recommendation */}
                          <div style={{
                            position: "absolute", top: "10px", left: "10px",
                            background: "rgba(233, 30, 99, 0.9)", color: "white",
                            padding: "4px 8px", borderRadius: "12px", fontSize: "10px", fontWeight: "bold", zIndex: 2
                          }}>
                            FOR YOU
                          </div>
                          <img
                            src={
                              product.image?.startsWith("http")
                                ? product.image
                                : `http://localhost:5000${product.image}`
                            }
                            alt={product.name}
                          />
                          <button
                            className={`wishlist-icon ${isWishlisted(product._id) ? "active" : ""}`}
                            onClick={(e) => {
                              e.stopPropagation();
                              isWishlisted(product._id) ? removeFromWishlist(product._id) : addToWishlist(product);
                            }}
                          >
                            {isWishlisted(product._id) ? "❤️" : "🤍"}
                          </button>
                        </div>

                        <div className="card-details">
                          <h4 className="product-name">{product.name}</h4>
                          <p style={{ fontSize: "1.1rem", fontWeight: "bold", margin: "5px 0" }}>₹{product.price}</p>
                          <div className="delivery-tag">Free Delivery</div>
                          <div className="rating-badge">
                            {product.rating ? product.rating.toFixed(1) : "0.0"} ★
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* 1. CATEGORY CIRCLES (Horizontal Scroll) */}
              <div className="category-circles-section">
                {["All", "Men", "Women", "Kids", "Accessories", "Sale"].map((cat) => (
                  <div
                    key={cat}
                    className={`category-circle-item ${filters.gender === cat || filters.category === cat ? "active" : ""}`}
                    onClick={() => {
                      if (cat === "All") {
                        setFilters({ ...filters, category: "", gender: "" });
                      } else if (["Men", "Women", "Kids"].includes(cat)) {
                        setFilters({ ...filters, gender: cat, category: "" });
                      } else {
                        setFilters({ ...filters, category: cat, gender: "" });
                      }
                    }}
                  >
                    <div className="circle-img-placeholder">
                      {cat === "All" ? "🛍️" : cat === "Men" ? "👕" : cat === "Women" ? "👗" : cat === "Kids" ? "🧸" : cat === "Accessories" ? "👜" : "🏷️"}
                    </div>
                    <span>{cat}</span>
                  </div>
                ))}
              </div>

              {/* 2. FILTER & SORT BAR (Sticky) */}
              <div className="filter-sort-bar">
                <div style={{ position: 'relative' }} ref={sortDropdownRef}>
                  <button
                    className={`filter-chip ${showSortDropdown || sortBy !== "relevance" ? 'active' : ''}`}
                    onClick={() => setShowSortDropdown(!showSortDropdown)}
                  >
                    ⇅ {sortBy === "relevance" ? "Sort" : SORT_OPTIONS.find(o => o.value === sortBy)?.label}
                  </button>
                  {showSortDropdown && (
                    <div className="sort-dropdown-menu">
                      {SORT_OPTIONS.map(opt => (
                        <div
                          key={opt.value}
                          className={`sort-option ${sortBy === opt.value ? 'selected' : ''}`}
                          onClick={() => {
                            setSortBy(opt.value);
                            setShowSortDropdown(false);
                          }}
                        >
                          {opt.label}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
                <div style={{ position: 'relative' }} ref={dropdownRef}>
                  <button
                    className={`filter-chip ${showCategoryDropdown || filters.category ? 'active' : ''}`}
                    onClick={() => setShowCategoryDropdown(!showCategoryDropdown)}
                  >
                    {filters.category ? filters.category : "Category ▼"}
                  </button>
                  {showCategoryDropdown && (
                    <div className="category-dropdown-menu">
                      {Object.keys(CATEGORY_OPTIONS).map(gender => (
                        <div key={gender} className="category-group">
                          <strong>{CATEGORY_OPTIONS[gender].icon} {gender}</strong>
                          <div className="category-list">
                            {/* View All Option */}
                            <span
                              className="cat-item view-all"
                              onClick={() => {
                                setFilters({
                                  ...filters,
                                  gender: gender === "Accessories" ? "" : gender,
                                  category: ""
                                });
                                setShowCategoryDropdown(false);
                              }}
                            >
                              View All {gender}
                            </span>

                            {CATEGORY_OPTIONS[gender].items.map(subCat => (
                              <span
                                key={subCat}
                                className={`cat-item ${filters.category === subCat ? 'selected' : ''}`}
                                onClick={() => {
                                  setFilters({
                                    ...filters,
                                    gender: gender === "Accessories" ? "" : gender,
                                    category: subCat
                                  });
                                  setShowCategoryDropdown(false);
                                }}
                              >
                                {subCat}
                              </span>
                            ))}
                          </div>
                        </div>
                      ))}
                      <div className="category-group">
                        <span
                          className="clear-cat-btn"
                          onClick={() => {
                            setFilters({ ...filters, category: "", gender: "" });
                            setShowCategoryDropdown(false);
                          }}
                        >
                          Clear Selection
                        </span>
                      </div>
                    </div>
                  )}
                </div>
                <button className="filter-chip" onClick={() => setShowFilterDrawer(true)}>
                  ⚙ Filters
                </button>

                {/* Quick Price Dropdown */}
                <select
                  className="quick-price-select"
                  onChange={(e) => {
                    const val = e.target.value;
                    if (val === "low") setFilters({ ...filters, minPrice: "", maxPrice: "500" });
                    else if (val === "mid") setFilters({ ...filters, minPrice: "500", maxPrice: "1000" });
                    else if (val === "high") setFilters({ ...filters, minPrice: "1000", maxPrice: "" });
                    else setFilters({ ...filters, minPrice: "", maxPrice: "" });
                  }}
                >
                  <option value="">Price: Any</option>
                  <option value="low">Under ₹500</option>
                  <option value="mid">₹500 - ₹1000</option>
                  <option value="high">Above ₹1000</option>
                </select>
              </div>

              {/* FILTER DRAWER (Modal) */}
              {showFilterDrawer && (
                <div className="filter-drawer-overlay" onClick={() => setShowFilterDrawer(false)}>
                  <div className="filter-drawer" onClick={(e) => e.stopPropagation()}>
                    <div className="drawer-header">
                      <h3>Filters</h3>
                      <button onClick={() => setShowFilterDrawer(false)}>✖</button>
                    </div>

                    <div className="drawer-section">
                      <h4>Gender</h4>
                      <div className="gender-options" style={{ display: 'flex', gap: '10px', flexWrap: 'wrap', marginBottom: '20px' }}>
                        {["Men", "Women", "Kids", "Unisex"].map(g => (
                          <button
                            key={g}
                            onClick={() => setFilters({ ...filters, gender: filters.gender === g ? "" : g })}
                            style={{
                              padding: '6px 12px',
                              borderRadius: '20px',
                              border: filters.gender === g ? '1px solid #e91e63' : '1px solid #ddd',
                              background: filters.gender === g ? '#fff0f6' : 'white',
                              color: filters.gender === g ? '#e91e63' : '#333',
                              cursor: 'pointer'
                            }}
                          >
                            {g}
                          </button>
                        ))}
                      </div>

                      <h4>Brand</h4>
                      <div className="brand-options" style={{ display: 'flex', gap: '10px', flexWrap: 'wrap', marginBottom: '20px' }}>
                        {brands.length > 0 ? (
                          brands.map(b => (
                            <label key={b} style={{ display: 'flex', alignItems: 'center', gap: '5px', fontSize: '14px', cursor: 'pointer' }}>
                              <input
                                type="radio"
                                name="brand"
                                checked={filters.brand === b}
                                onClick={() => setFilters({ ...filters, brand: filters.brand === b ? "" : b })}
                                readOnly
                                style={{ accentColor: '#e91e63' }}
                              />
                              {b}
                            </label>
                          ))
                        ) : (
                          <p style={{ fontSize: '13px', color: '#888' }}>No brands available.</p>
                        )}
                      </div>

                      <h4>Rating</h4>
                      <div className="rating-options" style={{ marginBottom: '20px' }}>
                        {[4, 3, 2].map(r => (
                          <div
                            key={r}
                            onClick={() => setFilters({ ...filters, minRating: filters.minRating === r ? "" : r })}
                            style={{
                              padding: '8px',
                              cursor: 'pointer',
                              background: filters.minRating === r ? '#f0f0f0' : 'transparent',
                              borderRadius: '5px',
                              marginBottom: '5px'
                            }}
                          >
                            {Array(r).fill("⭐").join("")} & up
                          </div>
                        ))}
                      </div>

                      <h4>Price Range</h4>
                      <div className="price-inputs" style={{ display: 'flex', gap: '10px' }}>
                        <input
                          type="number"
                          placeholder="Min ₹"
                          value={filters.minPrice}
                          onChange={(e) => setFilters({ ...filters, minPrice: e.target.value })}
                          style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                        />
                        <input
                          type="number"
                          placeholder="Max ₹"
                          value={filters.maxPrice}
                          onChange={(e) => setFilters({ ...filters, maxPrice: e.target.value })}
                          style={{ flex: 1, padding: '8px', border: '1px solid #ddd', borderRadius: '4px' }}
                        />
                      </div>
                    </div>

                    <div className="drawer-actions">
                      <button className="clear-btn" onClick={() => setFilters({ ...filters, minPrice: "", maxPrice: "" })}>Clear</button>
                      <button className="apply-btn" onClick={() => setShowFilterDrawer(false)}>Apply</button>
                    </div>
                  </div>
                </div>
              )}

              {/* 3. PRODUCT GRID */}
              <div className="catalog-grid-wrapper">
                {products.length === 0 ? (
                  <div className="empty-state" style={{ padding: "20px", textAlign: "center" }}>
                    <p>No products found fitting these criteria.</p>
                    <button
                      onClick={() => setFilters({ category: "", minPrice: "", maxPrice: "" })}
                      style={{ padding: "8px 16px", background: "#e91e63", color: "white", border: "none", borderRadius: "4px", cursor: "pointer" }}
                    >
                      Clear Filters
                    </button>
                  </div>
                ) : (
                  <div className="catalog-grid-smart">
                    {products.map((product) => (
                      <div key={product._id} className="smart-product-card">
                        <div className="card-image-container" onClick={() => navigate(`/product/${product._id}`, { state: product })} style={{ cursor: "pointer" }}>
                          <img
                            src={
                              product.image?.startsWith("http")
                                ? product.image
                                : `http://localhost:5000${product.image}`
                            }
                            alt={product.name}
                          />
                          <button
                            className={`wishlist-icon ${isWishlisted(product._id) ? "active" : ""}`}
                            onClick={(e) => {
                              e.stopPropagation();
                              isWishlisted(product._id) ? removeFromWishlist(product._id) : addToWishlist(product);
                            }}
                          >
                            {isWishlisted(product._id) ? "❤️" : "🤍"}
                          </button>
                        </div>

                        <div className="card-details">
                          <h4 className="product-name">{product.name}</h4>
                          <p style={{ fontSize: "1.1rem", fontWeight: "bold", margin: "5px 0" }}>₹{product.price}</p>
                          <div className="delivery-tag">Free Delivery</div>

                          {/* Rating Badge (Real) */}
                          <div className="rating-badge">
                            {product.rating ? product.rating.toFixed(1) : "0.0"} ★
                            <span className="rating-count">
                              ({product.reviews ? product.reviews.length : 0} reviews)
                            </span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
          )}

          {/* PROFILE */}
          {activeTab === "profile" && (
            <div className="profile-section">
              <h2>👤 My Profile</h2>

              <div className="profile-photo-box">
                <img src={avatarPhoto || "https://via.placeholder.com/120"} alt="Profile" className="profile-avatar" />
                <input type="file" accept="image/*" onChange={handlePhotoUpload} />
              </div>

              {/* Notice the safe access 'customer?.field || ""' */}
              <input
                type="text"
                placeholder="Full Name"
                value={customer?.name || ""}
                onChange={(e) => setCustomer({ ...customer, name: e.target.value })}
              />

              <input
                type="email"
                placeholder="Email"
                value={customer?.email || ""}
                disabled // Cannot change email as it identifies the account
                onChange={(e) => setCustomer({ ...customer, email: e.target.value })}
              />

              <input
                type="text"
                placeholder="Phone Number"
                value={customer?.phone || ""}
                onChange={(e) => setCustomer({ ...customer, phone: e.target.value })}
              />

              <select
                value={customer?.gender || ""}
                onChange={(e) => setCustomer({ ...customer, gender: e.target.value })}
              >
                <option value="">Select Gender</option>
                <option value="male">Male</option>
                <option value="female">Female</option>
                <option value="other">Other</option>
              </select>

              <h3>📍 Address</h3>

              <input
                type="text"
                placeholder="Door No / House Name"
                value={customer?.addressLine1 || ""}
                onChange={(e) => setCustomer({ ...customer, addressLine1: e.target.value })}
              />

              <input
                type="text"
                placeholder="Street / Road"
                value={customer?.addressLine2 || ""}
                onChange={(e) => setCustomer({ ...customer, addressLine2: e.target.value })}
              />

              <input
                type="text"
                placeholder="City"
                value={customer?.city || ""}
                onChange={(e) => setCustomer({ ...customer, city: e.target.value })}
              />

              <input
                type="text"
                placeholder="Pincode"
                value={customer?.pincode || ""}
                onChange={(e) => setCustomer({ ...customer, pincode: e.target.value })}
              />

              <button className="save-profile-btn" onClick={handleProfileUpdate}>
                Save Changes
              </button>
            </div>
          )}
          {activeTab === "avatar" && (
            <div className="avatar-section" style={{ display: "flex", flexDirection: "column", height: "80vh", padding: "10px" }}>

              {/* GENDER SELECTION (If not set or editable) */}
              {(!measurements.gender && isMeasurementEditable) ? (
                <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
                  <h2>Select Your Body Type</h2>
                  <div style={{ display: "flex", gap: "20px", marginTop: "20px" }}>
                    <button
                      onClick={() => setMeasurements({
                        gender: "female",
                        chest: "", waist: "", hips: "", thigh: "", shoulders: ""
                      })}
                      style={{ padding: "20px 40px", fontSize: "1.2rem", borderRadius: "10px", border: "2px solid #e91e63", background: "white", cursor: "pointer" }}
                    >
                      👩 Female
                    </button>
                    <button
                      onClick={() => setMeasurements({
                        gender: "male",
                        chest: "", waist: "", hips: "", thigh: "", shoulders: ""
                      })}
                      style={{ padding: "20px 40px", fontSize: "1.2rem", borderRadius: "10px", border: "2px solid #2196f3", background: "white", cursor: "pointer" }}
                    >
                      👨 Male
                    </button>
                  </div>
                </div>
              ) : (
                <div style={{ display: "flex", gap: "20px", height: "100%" }}>
                  {/* LEFT: Inputs & Button - Compact Layout */}
                  <div style={{ width: "250px", display: "flex", flexDirection: "column", gap: "8px", justifyContent: "center" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                      <h2 style={{ fontSize: "1.2rem", margin: "0" }}>Measurements</h2>
                    </div>

                    <div style={{ background: '#f0f0f0', padding: '10px', borderRadius: '5px', marginBottom: '10px', marginTop: '10px' }}>
                      <p style={{ margin: 0, fontWeight: 'bold', fontSize: '0.9rem' }}>
                        Body Type: {measurements.gender === "male" ? "👨 Male" : "👩 Female"}
                      </p>
                      {isMeasurementEditable && (
                        <button
                          onClick={() => setMeasurements({ ...measurements, gender: "" })}
                          style={{ marginTop: '5px', fontSize: "0.8rem", padding: "5px 10px", cursor: "pointer", background: "#fff", border: "1px solid #ccc", borderRadius: "4px" }}
                        >
                          🔄 Change Gender
                        </button>
                      )}
                    </div>

                    <div style={{ margin: "10px 0", borderTop: "1px solid #ddd", paddingTop: "10px" }}>
                      <label style={{ display: "block", fontSize: "0.9rem", fontWeight: "bold", marginBottom: "5px" }}>Upload Face Photo (Selfie)</label>
                      <input
                        type="file"
                        accept="image/*"
                        onChange={(e) => {
                          if (e.target.files && e.target.files[0]) {
                            // You can save this file to state or upload it to generate a detailed 3D mesh later
                            console.log("Uploaded Face Photo:", e.target.files[0]);
                            alert("Face photo selected! A 3D Face would be generated from this.");
                          }
                        }}
                        style={{ fontSize: "0.8rem" }}
                      />
                    </div>

                    {["chest", "waist", "hips", "thigh", "shoulders"].map((m) => {
                      let options = [];
                      let label = m.toUpperCase();

                      if (m === "chest") {
                        label += " (IN)";
                        for (let i = 28; i <= 48; i++) options.push(i);
                      } else if (m === "waist") {
                        label += " (IN)";
                        for (let i = 28; i <= 48; i++) options.push(i);
                      } else if (m === "hips") {
                        label += " (IN)";
                        const max = measurements.gender === "male" ? 36 : 48;
                        for (let i = 28; i <= max; i++) options.push(i);
                      } else if (m === "thigh") {
                        label += " (IN)";
                        for (let i = 19; i <= 25; i++) options.push(i);
                      } else if (m === "shoulders") {
                        label += " (IN)";
                        for (let i = 13; i <= 15; i++) options.push(i);
                      }

                      return (
                        <div key={m} style={{ display: 'flex', flexDirection: 'column' }}>
                          <label style={{ fontSize: '11px', fontWeight: 'bold', marginBottom: '2px', color: "#555" }}>{label}</label>
                          <select
                            name={m}
                            value={measurements[m]}
                            onChange={handleMeasurementChange}
                            disabled={!isMeasurementEditable}
                            style={{
                              padding: '6px',
                              fontSize: '13px',
                              borderRadius: "4px",
                              border: "1px solid #ccc",
                              backgroundColor: !isMeasurementEditable ? "#f0f0f0" : "#fff",
                              cursor: !isMeasurementEditable ? "not-allowed" : "pointer"
                            }}
                          >
                            <option value="">Select</option>
                            {options.map(val => (
                              <option key={val} value={val}>{val}</option>
                            ))}
                          </select>
                        </div>
                      );
                    })}

                    {isMeasurementEditable ? (
                      <button
                        onClick={handleGenerateAvatar}
                        style={{
                          marginTop: "10px",
                          padding: "10px",
                          backgroundColor: "#e91e63",
                          color: "white",
                          border: "none",
                          borderRadius: "5px",
                          cursor: "pointer",
                          fontWeight: "bold",
                          fontSize: "14px"
                        }}
                      >
                        💾 Generate & Save
                      </button>
                    ) : (
                      <button
                        onClick={() => setIsMeasurementEditable(true)}
                        style={{
                          marginTop: "10px",
                          padding: "10px",
                          backgroundColor: "#333",
                          color: "white",
                          border: "none",
                          borderRadius: "5px",
                          cursor: "pointer",
                          fontWeight: "bold",
                          fontSize: "14px"
                        }}
                      >
                        🖊️ Edit Measurements
                      </button>
                    )}
                  </div>

                  {/* RIGHT: Avatar Viewer */}
                  <div style={{ flex: 1, backgroundColor: "#fff", borderRadius: "10px", border: "1px solid #eee", overflow: "hidden", position: "relative" }}>
                    <div style={{ width: "100%", height: "100%" }}>
                      <AvatarViewer
                        measurements={{
                          gender: measurements.gender,
                          chest: Number(measurements.chest),
                          waist: Number(measurements.waist),
                          hips: Number(measurements.hips),
                          thigh: Number(measurements.thigh),
                          shoulders: Number(measurements.shoulders),
                        }}
                        modelUrl={measurements.gender === "male" ? "/models/male_base.glb" : "/models/female_base.glb"}
                        clothingModelUrl={selectedClothing}
                      />
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}


          {/* ORDERS */}
          {activeTab === "orders" && (
            <div className="orders-section">
              <h2>My Orders</h2>
              {orderHistory.length === 0 ? (
                <p>No orders found.</p>
              ) : (
                <div className="order-list">
                  {orderHistory.map((order) => (
                    <div key={order._id} className="order-card" style={{ border: "1px solid #ddd", padding: "15px", marginBottom: "15px", borderRadius: "8px" }}>
                      <div className="order-header" style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px", borderBottom: "1px solid #eee", paddingBottom: "5px" }}>
                        <span><strong>Date:</strong> {new Date(order.createdAt).toLocaleDateString()}</span>
                        <span><strong>Status:</strong> <span style={{ color: order.status === "Delivered" ? "green" : "orange" }}>{order.status}</span></span>
                        <span><strong>Total:</strong> ₹{order.totalAmount}</span>
                        <button
                          onClick={() => navigate(`/order/${order._id}`)}
                          style={{
                            padding: "5px 10px",
                            backgroundColor: "#2196f3",
                            color: "white",
                            border: "none",
                            borderRadius: "4px",
                            cursor: "pointer",
                            fontSize: "0.8rem"
                          }}
                        >
                          Track Order
                        </button>
                      </div>
                      <div className="order-items">
                        {order.items.map((item, idx) => (
                          <div key={idx} style={{ display: "flex", alignItems: "center", gap: "10px", marginBottom: "5px" }}>
                            <img
                              src={item.image?.startsWith("http") ? item.image : `http://localhost:5000${item.image}`}
                              alt={item.name}
                              style={{ width: "50px", height: "50px", objectFit: "cover", borderRadius: "4px" }}
                            />
                            <div>
                              <p style={{ margin: 0, fontWeight: "bold" }}>{item.name}</p>
                              <p style={{ margin: 0, fontSize: "0.9rem", color: "#666" }}>Qty: {item.quantity} | ₹{item.price}</p>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* CART */}
          {activeTab === "cart" && (
            <div className="cart-section">
              <h2>🛒 Your Cart</h2>

              {cart.items.length === 0 ? (
                <p>Your cart is empty.</p>
              ) : (
                cart.items.map((item) => (
                  <div key={item._id || item.id} className="cart-item">
                    <img
                      src={
                        item.image?.startsWith("http")
                          ? item.image
                          : `http://localhost:5000${item.image}`
                      }
                      alt={item.name}
                      className="cart-item-img"
                    />

                    <div>
                      <h4>{item.name}</h4>
                      <p>₹{item.price}</p>

                      <div className="quantity-box">
                        <button onClick={() => updateQuantity(item._id || item.id, item.quantity - 1)}>-</button>
                        <span>{item.quantity}</span>
                        <button onClick={() => updateQuantity(item._id || item.id, item.quantity + 1)}>+</button>
                      </div>
                    </div>

                    <div className="cart-actions">
                      <button
                        className="wishlist-move-btn"
                        onClick={() => {
                          addToWishlist(item);
                          removeFromCart(item._id || item.id);
                          toast.success(`❤️ Moved ${item.name} to wishlist`);
                        }}
                      >
                        ❤️ Move to Wishlist
                      </button>

                      <button
                        className="remove-btn"
                        onClick={() => removeFromCart(item._id || item.id)}
                      >
                        🗑 Remove
                      </button>
                    </div>
                  </div>
                ))
              )}

              <h3>Total: ₹{getCartTotal()}</h3>

              <button className="primary-btn" onClick={handlePlaceOrder}>
                Place Order
              </button>
            </div>
          )}

          {/* WISHLIST */}
          {activeTab === "wishlist" && (
            <div className="wishlist-section">
              <h2>My Wishlist ❤️</h2>

              {wishlist.length === 0 ? (
                <p>Your wishlist is empty.</p>
              ) : (
                wishlist.map((item) => (
                  <div key={item._id || item.id} className="wishlist-item">
                    <img
                      src={item.image?.startsWith("http") ? item.image : `http://localhost:5000${item.image}`}
                      alt={item.name}
                      className="wishlist-img"
                    />

                    <div className="wishlist-info">
                      <h4>{item.name}</h4>
                      <p>₹{item.price}</p>
                    </div>

                    <div className="wishlist-actions">
                      <button
                        className="addcart-btn"
                        onClick={() => {
                          addToCart({ ...item, id: item._id || item.id });
                          removeFromWishlist(item._id || item.id);
                          toast.success(`🛍️ ${item.name} moved to cart!`);
                        }}
                      >
                        🛒 Add to Cart
                      </button>

                      <button
                        className="remove-btn"
                        onClick={() => removeFromWishlist(item._id || item.id)}
                      >
                        🗑 Remove
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          )}
          {/* HISTORY */}
          {activeTab === "history" && (
            <div className="history-section" style={{ padding: '20px' }}>
              <h2>🕒 Virtual Try-On History</h2>
              {!customer.tryOnHistory || customer.tryOnHistory.length === 0 ? (
                <p>You haven't tried on any clothes yet.</p>
              ) : (
                <div className="catalog-grid-smart">
                  {customer.tryOnHistory.map((item, idx) => (
                    <div key={idx} className="smart-product-card" onClick={() => navigate(`/product/${item.productId}`)} style={{ cursor: 'pointer' }}>
                      <div className="card-image-container">
                        <img
                          src={item.productImage?.startsWith("http") ? item.productImage : `http://localhost:5000${item.productImage}`}
                          alt={item.productName}
                        />
                      </div>
                      <div className="card-details">
                        <h4>{item.productName}</h4>
                        <p style={{ fontSize: '0.8rem', color: '#666' }}>Tried on {new Date(item.triedAt).toLocaleDateString()}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </main>
      </div >
    </div >
  );
};

export default CustomerDashboard;

import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";

const Login = ({ setUser }) => {
  const [formData, setFormData] = useState({ email: "", password: "" });
  const [showPassword, setShowPassword] = useState(false);
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setLoading(true);

    try {
      // ✅ Hardcoded Admin Login
      if (formData.email === "admin@smartstyle.com" && formData.password === "admin123") {
        const adminUser = {
          name: "Admin",
          email: formData.email,
          role: "admin",
        };

        localStorage.setItem("user", JSON.stringify(adminUser));
        localStorage.setItem("token", "admin-token");

        setUser(adminUser);
        setSuccess("Admin login successful!");
        setLoading(false);

        navigate("/admin-dashboard");
        return;
      }

      // ✅ Normal user login (Customer or Vendor)
      const response = await fetch(`${process.env.REACT_APP_API_URL || "http://localhost:5000"}/api/auth/login`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: formData.email.trim(),
          password: formData.password.trim(),
        }),
      });

      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.message || "Login failed");
      }

      const data = await response.json();

      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));

      setUser(data.user);
      setSuccess("Login successful! Redirecting...");
      setLoading(false);

      // ✅ Redirect based on role
      if (data.user.role === "customer") {
        navigate("/customer-dashboard");
      } else if (data.user.role === "vendor") {
        navigate("/vendor-dashboard");
      } else {
        throw new Error("Unknown role");
      }
    } catch (err) {
      setLoading(false);
      setError(err.message);
    }
  };

  return (
    <div className="login-page">
      <div className="login-wrapper">
        {/* LEFT SIDE: Promotional / Branding (Flipkart style) */}
        <div className="login-left">
          <div className="login-content">
            <h2>Login</h2>
            <p>Get access to your Orders, Wishlist and Recommendations</p>
            <div className="promo-illustration">
              🛍️
            </div>
          </div>
        </div>

        {/* RIGHT SIDE: Form */}
        <div className="login-right">
          <form onSubmit={handleLogin} className="login-form-groups">
            <div className="floating-input-group">
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
                className="floating-input"
                placeholder=" "
              />
              <label className="floating-label">Enter Email/Mobile number</label>
            </div>

            <div className="floating-input-group">
              <input
                type={showPassword ? "text" : "password"}
                name="password"
                value={formData.password}
                onChange={handleChange}
                required
                className="floating-input"
                placeholder=" "
              />
              <label className="floating-label">Enter Password</label>
              <span
                className="password-toggle"
                onClick={() => setShowPassword(!showPassword)}
                role="button"
                tabIndex={0}
              >
                {showPassword ? (
                  /* Eye Off Icon (Hide) */
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#878787" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path>
                    <line x1="1" y1="1" x2="23" y2="23"></line>
                  </svg>
                ) : (
                  /* Eye Icon (Show) */
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#878787" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                    <circle cx="12" cy="12" r="3"></circle>
                  </svg>
                )}
              </span>
            </div>

            <div className="form-footer-text">
              By continuing, you agree to SmartStyle's <a href="#">Terms of Use</a> and <a href="#">Privacy Policy</a>.
            </div>

            <button type="submit" className="login-submit-btn" disabled={loading}>
              {loading ? "Logging in..." : "Login"}
            </button>

            {/* Removed OTP section per request */}

            <div className="login-links">
              <Link to="/forgot-password" style={{ textDecoration: 'none', color: '#2874f0' }}>Forgot Password?</Link>
              <br />
              <span style={{ color: "#333", fontSize: "0.9rem", marginTop: "10px", display: "block" }}>
                New to SmartStyle? <Link to="/signup">Create an account</Link>
              </span>
            </div>

            {error && <p className="error-text">{error}</p>}
            {success && <p className="success-text">{success}</p>}
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import { useCart } from "../context/CartContext";
import { useWishlist } from "../context/WishlistContext";
import AvatarViewer from "../components/AvatarViewer";
import ARViewer from "../components/ARViewer";
import { toast } from "react-toastify";
import "./ProductDetails.css"; // We will create this next
import axios from "axios";

const ProductDetails = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const location = useLocation();
    const { addToCart } = useCart();
    const { addToWishlist, isWishlisted, removeFromWishlist } = useWishlist();

    // use location.state if passed from dashboard to avoid immediate fetch delay
    const [product, setProduct] = useState(location.state || null);
    const [loading, setLoading] = useState(!location.state);
    const [showTryOn, setShowTryOn] = useState(false);
    const [overrideModel, setOverrideModel] = useState(null);
    const [isDemoMode, setIsDemoMode] = useState(false);
    const [relatedProducts, setRelatedProducts] = useState([]); // New State
    const [selectedSize, setSelectedSize] = useState(""); // Track user size choice
    const [showAR, setShowAR] = useState(false); // New AR State

    // --- Review State & Handler ---
    const [newReview, setNewReview] = useState({ rating: 5, comment: "" });

    const handleSubmitReview = async () => {
        const userUser = localStorage.getItem("user");
        if (!userUser) return toast.error("Please login to review");
        const parsedUser = JSON.parse(userUser);

        if (!newReview.comment.trim()) return toast.warn("Please write a comment");

        try {
            const res = await axios.post(`http://localhost:5000/api/products/reviews/${product._id}`, {
                userId: parsedUser.email,
                userName: parsedUser.name,
                rating: Number(newReview.rating),
                comment: newReview.comment
            });
            setProduct(res.data);
            setNewReview({ rating: 5, comment: "" });
            toast.success("Review Submitted!");
        } catch (err) {
            console.error(err);
            toast.error("Failed to submit review");
        }
    };

    // Load measurements from local storage or fallback to defaults
    const [measurements, setMeasurements] = useState(() => {
        const saved = localStorage.getItem("userMeasurements");
        // Ensure values are numbers for safe arithmetic
        if (saved) {
            return JSON.parse(saved);
        }
        return { chest: 34, waist: 28, hips: 38, thigh: 20, shoulders: 15, height: 170, weight: 60, gender: "female" };
    });

    useEffect(() => {
        if (!product) {
            axios.get(`http://localhost:5000/api/products/${id}`)
                .then(res => {
                    setProduct(res.data);
                    setLoading(false);
                })
                .catch(err => {
                    console.error(err);
                    toast.error("Failed to load product");
                    setLoading(false);
                });
        }
    }, [id, product]);

    // --- Fetch Related Products ---
    useEffect(() => {
        if (product?.category) {
            axios.get(`http://localhost:5000/api/products?category=${product.category}`)
                .then(res => {
                    // Filter out current product and limiting to 4
                    const others = res.data.filter(p => p._id !== product._id).slice(0, 4);
                    setRelatedProducts(others);
                })
                .catch(err => console.error("Failed to load related products", err));
        }
    }, [product]);

    if (loading) return <div className="loading">Loading Product Details...</div>;
    if (!product) return <div className="error">Product not found.</div>;

    return (
        <div className="product-details-container">
            <button className="back-btn" onClick={() => navigate(-1)}>← Back</button>

            <div className="product-layout">
                {/* Left: Image / TryOn */}
                <div className="product-visual">
                    {showTryOn ? (
                        <div className="tryon-container">
                            <AvatarViewer
                                measurements={{
                                    height: Number(measurements.height),
                                    weight: Number(measurements.weight),
                                    chest: Number(measurements.chest),
                                    waist: Number(measurements.waist),
                                    hips: Number(measurements.hips),
                                    thigh: Number(measurements.thigh),
                                    shoulders: Number(measurements.shoulders),
                                    gender: measurements.gender
                                }}
                                clothingModelUrl={product.model3D ? (product.model3D.startsWith('http') ? product.model3D : `http://localhost:5000${product.model3D}`) : null}
                                modelUrl={measurements.gender === 'male' ? "/models/male_base.glb" : "/models/female_base.glb"}
                                sizeChartData={product.sizeChart}
                                availableSizes={product.sizes}
                                initialSize={selectedSize || (product.sizes && product.sizes[0])}
                                key={showTryOn ? `active-${product._id}` : "inactive"}
                            />
                            <button className="close-tryon" onClick={() => setShowTryOn(false)}>Close Try-On</button>
                        </div >
                    ) : (
                        <img
                            src={product.image?.startsWith("http") ? product.image : `http://localhost:5000${product.image}`}
                            alt={product.name}
                            className="main-product-img"
                        />
                    )}
                </div >

                {/* Right: Details */}
                < div className="product-info" >
                    <h1>{product.name}</h1>
                    <p className="price">₹{product.price}</p>

                    <div className="stock-status">
                        {product.stock > 0 ? (
                            <span className="in-stock">✅ In Stock ({product.stock} left)</span>
                        ) : (
                            <span className="out-of-stock">❌ Out of Stock</span>
                        )}
                    </div>

                    <p className="description">
                        {product.description || "No description available for this product. High quality fabric and premium stitch."}
                    </p>

                    <p className="category">Category: <strong>{product.category}</strong></p>

                    <div className="action-buttons">
                        <button
                            className="buy-now-btn"
                            disabled={product.stock <= 0}
                            onClick={() => {
                                addToCart({ ...product, id: product._id });
                                navigate("/cart");
                            }}
                        >
                            Buy Now
                        </button>

                        <button
                            className="add-cart-btn"
                            disabled={product.stock <= 0}
                            onClick={() => {
                                addToCart({ ...product, id: product._id });
                                toast.success("Added to Cart!");
                            }}
                        >
                            Add to Cart
                        </button>

                        <button
                            className={`wishlist-action-btn ${isWishlisted(product._id) ? "active" : ""}`}
                            onClick={() => isWishlisted(product._id) ? removeFromWishlist(product._id) : addToWishlist(product)}
                        >
                            {isWishlisted(product._id) ? "❤️ Wishlisted" : "🤍 Add to Wishlist"}
                        </button>
                    </div>

                    {/* TRY ON TRIGGER - Only if Model Exists */}
                    {product.model3D && (
                        <div className="tryon-section" style={{ marginTop: '20px', padding: '15px', background: '#f5f5f5', borderRadius: '8px' }}>
                            <h3>Virtual Experience</h3>
                            <p>See how this looks on your 3D avatar!</p>

                            {product.sizes && product.sizes.length > 0 && (
                                <div style={{ marginBottom: "15px" }}>
                                    <strong>Select a Size to Try On:</strong>
                                    <div style={{ display: 'flex', gap: '8px', marginTop: '8px' }}>
                                        {product.sizes.map(sz => (
                                            <button
                                                key={sz}
                                                onClick={() => setSelectedSize(sz)}
                                                style={{
                                                    padding: "8px 12px", border: "1px solid #ccc", borderRadius: "5px", cursor: "pointer",
                                                    background: selectedSize === sz ? "#000" : "#fff",
                                                    color: selectedSize === sz ? "#fff" : "#000",
                                                    fontWeight: "bold"
                                                }}
                                            >
                                                {sz}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            )}

                            <button
                                className="tryon-launch-btn"
                                style={{ width: '100%', padding: '12px', background: '#2196F3', color: 'white', border: 'none', borderRadius: '5px', fontWeight: 'bold', cursor: 'pointer', transition: '0.3s' }}
                                onClick={() => {
                                    if (product.sizes?.length > 0 && !selectedSize) {
                                        return toast.error("Please select a size first!");
                                    }

                                    setIsDemoMode(false);
                                    setOverrideModel(null);
                                    setShowTryOn(true);

                                    // Save History
                                    const uStr = localStorage.getItem("user");
                                    if (uStr) {
                                        const u = JSON.parse(uStr);
                                        if (u.email) {
                                            axios.post(`http://localhost:5000/api/customer/${u.email}/tryon`, {
                                                productId: product._id,
                                                productName: product.name,
                                                productImage: product.image
                                            }).catch(e => console.log("History log failed", e));
                                        }
                                    }
                                }}>
                                👕 Try This Product
                            </button>

                            {/* AR BUTTON */}
                            <button
                                style={{ width: '100%', padding: '12px', background: '#9c27b0', color: 'white', border: 'none', borderRadius: '5px', fontWeight: 'bold', cursor: 'pointer', transition: '0.3s', marginTop: '10px' }}
                                onClick={() => setShowAR(true)}
                            >
                                🔍 View in AR (Mobile)
                            </button>
                        </div>
                    )}
                </div >
            </div >

            {/* RELATED PRODUCTS SECTION */}
            {
                relatedProducts.length > 0 && (
                    <div className="related-products-section">
                        <h2>You May Also Like</h2>
                        <div className="related-grid">
                            {relatedProducts.map((rp) => (
                                <div key={rp._id} className="related-card" onClick={() => {
                                    setProduct(rp); // Update current view immediately
                                    navigate(`/product/${rp._id}`, { state: rp });
                                    window.scrollTo(0, 0); // Scroll top
                                }}>
                                    <img
                                        src={rp.image?.startsWith("http") ? rp.image : `http://localhost:5000${rp.image}`}
                                        alt={rp.name}
                                    />
                                    <h4>{rp.name}</h4>
                                    <p>₹{rp.price}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                )
            }

            {/* REVIEWS SECTION */}
            <div className="reviews-section">
                <h2>Customer Reviews ({product.reviews?.length || 0})</h2>
                <div className="average-rating-display">
                    <span className="stars-large">{"★".repeat(Math.round(product.rating || 0)) + "☆".repeat(5 - Math.round(product.rating || 0))}</span>
                    <span className="rating-text">{product.rating?.toFixed(1) || 0} / 5</span>
                </div>

                <div className="reviews-list">
                    {product.reviews && product.reviews.length > 0 ? (
                        product.reviews.slice().reverse().map((rev, idx) => (
                            <div key={idx} className="review-card">
                                <div className="review-avatar">{rev.userName.charAt(0).toUpperCase()}</div>
                                <div className="review-content">
                                    <div className="review-header">
                                        <strong>{rev.userName}</strong>
                                        <span className="review-date">{new Date(rev.createdAt).toLocaleDateString()}</span>
                                    </div>
                                    <div className="review-stars">
                                        {"★".repeat(rev.rating) + "☆".repeat(5 - rev.rating)}
                                    </div>
                                    <p className="review-text">{rev.comment}</p>
                                </div>
                            </div>
                        ))
                    ) : (
                        <p className="no-reviews">No reviews yet. Be the first to share your thoughts!</p>
                    )}
                </div>

                <div className="add-review-form">
                    <h3>Write a Review</h3>
                    <div className="review-inputs">
                        <select
                            value={newReview.rating}
                            onChange={(e) => setNewReview({ ...newReview, rating: Number(e.target.value) })}
                        >
                            <option value="5">⭐⭐⭐⭐⭐ (Excellent)</option>
                            <option value="4">⭐⭐⭐⭐ (Good)</option>
                            <option value="3">⭐⭐⭐ (Average)</option>
                            <option value="2">⭐⭐ (Poor)</option>
                            <option value="1">⭐ (Terrible)</option>
                        </select>
                        <textarea
                            placeholder="Share your experience with this product..."
                            value={newReview.comment}
                            onChange={(e) => setNewReview({ ...newReview, comment: e.target.value })}
                        />
                        <button className="submit-review-btn" onClick={handleSubmitReview}>Submit Review</button>
                    </div>
                </div>
            </div>

            {/* AR FULL SCREEN OVERLAY */}
            {showAR && product.model3D && (
                <ARViewer
                    modelUrl={product.model3D.startsWith('http') ? product.model3D : `http://localhost:5000${product.model3D}`}
                    onClose={() => setShowAR(false)}
                />
            )}
        </div >
    );
};

export default ProductDetails;

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';

const ResetPassword = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [tokenValid, setTokenValid] = useState(false);
  const [formData, setFormData] = useState({
    newPassword: '',
    confirmPassword: ''
  });

  const token = searchParams.get('token');

  useEffect(() => {
    // Verify token when component loads
    if (token) {
      verifyToken();
    }
  }, [token]);

  const verifyToken = async () => {
    try {
      const response = await fetch(`http://localhost:5000/api/auth/verify-reset-token/${token}`);
      if (response.ok) {
        setTokenValid(true);
      } else {
        setError('Invalid or expired reset link');
      }
    } catch (error) {
      setError('Error verifying reset link');
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (formData.newPassword !== formData.confirmPassword) {
      setError('Passwords do not match');
      setLoading(false);
      return;
    }

    try {
      const response = await fetch('http://localhost:5000/api/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          token: token,
          newPassword: formData.newPassword
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message);
      }

      setSuccess('Password reset successfully! Redirecting to login...');
      setTimeout(() => {
        navigate('/login');
      }, 3000);

    } catch (error) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  if (!token) {
    return (
      <div className="login-container">
        <div className="login-box">
          <h2>Invalid Reset Link</h2>
          <p>No reset token provided.</p>
          <button onClick={() => navigate('/login')} className="submit-btn">
            Back to Login
          </button>
        </div>
      </div>
    );
  }

  if (!tokenValid && !error) {
    return (
      <div className="login-container">
        <div className="login-box">
          <h2>Verifying Link...</h2>
          <p>Please wait while we verify your reset link.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="login-container">
      <div className="login-box">
        <h2>Reset Your Password</h2>
        
        {error && <div className="error-message">{error}</div>}
        {success && <div className="success-message">{success}</div>}

        {tokenValid && (
          <form onSubmit={handleSubmit} className="login-form">
            <input
              type="password"
              name="newPassword"
              placeholder="New Password"
              className="form-input"
              value={formData.newPassword}
              onChange={(e) => setFormData({...formData, newPassword: e.target.value})}
              required
              minLength={6}
            />
            
            <input
              type="password"
              name="confirmPassword"
              placeholder="Confirm New Password"
              className="form-input"
              value={formData.confirmPassword}
              onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})}
              required
              minLength={6}
            />

            <button type="submit" className="submit-btn" disabled={loading}>
              {loading ? 'Resetting...' : 'Reset Password'}
            </button>
          </form>
        )}

        <button onClick={() => navigate('/login')} className="toggle-btn">
          Back to Login
        </button>
      </div>
    </div>
  );
};

export default ResetPassword;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import AvatarViewer from '../components/AvatarViewer';

const VirtualTryOn = () => {
  const navigate = useNavigate();
  const [selectedProducts, setSelectedProducts] = useState([]);
  const [outfitHistory, setOutfitHistory] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('browse');

  // FACE PARAMS STATE
  const [faceParams, setFaceParams] = useState(JSON.parse(localStorage.getItem('faceParams')) || null);
  const [isFaceLoading, setIsFaceLoading] = useState(false);

  const handleFaceUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setIsFaceLoading(true);
    const formData = new FormData();
    formData.append('photo', file);

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/avatar/face-from-photo`, {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (data.success) {
        setFaceParams(data.faceParams);
        localStorage.setItem('faceParams', JSON.stringify(data.faceParams));
        alert("✅ Face Generated Successfully! Switch to Preview to see changes.");
      } else {
        alert("❌ Error: " + (data.message || 'Face analysis failed'));
      }
